#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

struct Point {
    double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0u, 0u, 0u, 0u};

    const int max_threads = omp_get_max_threads();
    std::vector<std::array<std::size_t, 4>> local(static_cast<std::size_t>(max_threads),
                                                  {0u, 0u, 0u, 0u});

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto &lb = local[static_cast<std::size_t>(tid)];

        #pragma omp for
        for (std::size_t i = 0; i < points.size(); ++i) {
            const double x = points[i].x;
            const double y = points[i].y;

            // Quadrants (including axes) mapped as:
            // 0: x>=0, y>=0
            // 1: x< 0, y>=0
            // 2: x< 0, y< 0
            // 3: x>=0, y< 0
            std::size_t q;
            if (x >= 0.0) {
                q = (y >= 0.0) ? 0u : 3u;
            } else {
                q = (y >= 0.0) ? 1u : 2u;
            }
            lb[q] += 1u;
        }
    }

    for (int t = 0; t < max_threads; ++t) {
        bins[0] += local[static_cast<std::size_t>(t)][0];
        bins[1] += local[static_cast<std::size_t>(t)][1];
        bins[2] += local[static_cast<std::size_t>(t)][2];
        bins[3] += local[static_cast<std::size_t>(t)][3];
    }
}
